import * as T from'../vendor/three.module.js';
import{World as OriginalWorld}from'../world.js';
import{hash,moveGround}from'./core.js';
import{join}from'../sunny/plants.js?v=2';
export const herbs=[{name:'高原牧草',note:'草甸与林缘 · 可喂牦牛',color:'#91ad61'},{name:'蓝花龙胆',note:'山地草甸 · 蓝紫色花簇',color:'#9c9acb'},{name:'林下野花',note:'阴湿林缘 · 随湿度生长',color:'#d5a194'},{name:'高山银莲',note:'林线上方 · 稀疏花甸',color:'#e8ddae'}];
function mergeGroup(group,exclude=[]){const buckets=new Map();for(const child of[...group.children]){if(!child.isMesh||exclude.includes(child))continue;child.updateMatrix();const id=child.material.uuid;if(!buckets.has(id))buckets.set(id,{material:child.material,parts:[]});buckets.get(id).parts.push(child.geometry.clone().applyMatrix4(child.matrix));group.remove(child);}for(const {parts,material}of buckets.values()){const m=new T.Mesh(join(parts),material);m.castShadow=true;m.receiveShadow=true;group.add(m);parts.forEach(g=>g.dispose());}}
export class Companions{
 constructor(scene,geo,landscape){this.scene=scene;this.geo=geo;this.landscape=landscape;this.ground=(x,z)=>landscape.bridgeAt(x,z)??geo.height(x,z);this.walkGeo={height:this.ground,waterAt:(x,z)=>landscape.bridgeAt(x,z)!==null?null:geo.waterAt(x,z)};this.animals=[];this.factory={scene,animals:this.animals};this.home=null;}
 build(spawn){for(const [type,x,z,id]of[['horse',spawn.x+7,spawn.z+8,0],['dog',spawn.x-4,spawn.z+6,1],...Array.from({length:5},(_,i)=>['yak',spawn.x+40+hash(i,3)*35,spawn.z-10+hash(i,5)*60,i+2])]){const p=this.geo.safePoint(x,z,35,(x,z)=>this.landscape.collides(x,z,.8)||this.landscape.obstacleTest?.(x,z)),a=OriginalWorld.prototype.animal.call(this.factory,type,p.x,p.z,id);a.group.position.y=p.y;if(type==='horse'){const leather=new T.MeshStandardMaterial({color:'#493b2a',roughness:.88}),blanket=new T.Mesh(new T.BoxGeometry(1.04,.10,1.02),new T.MeshStandardMaterial({color:'#6f897d',roughness:.96}));blanket.position.set(0,2.17,.04);a.group.add(blanket);for(const side of[-1,1]){const points=[[side*.22,2.95,-1.14],[side*.24,2.73,-1.45],[side*.22,2.61,-1.60],[side*.31,2.46,-.25]].map(p=>new T.Vector3(...p)),rein=new T.Mesh(new T.TubeGeometry(new T.CatmullRomCurve3(points),14,.022,5,false),leather);a.group.add(rein);}const blaze=new T.Mesh(new T.SphereGeometry(1,10,8),new T.MeshStandardMaterial({color:'#d9cba8',roughness:.94}));blaze.position.set(0,2.84,-1.65);blaze.scale.set(.04,.14,.022);a.group.add(blaze);}a.tailRestX=a.tail?.rotation.x||0;mergeGroup(a.group,[a.tail]);for(const leg of a.legs)mergeGroup(leg);a.group.scale.setScalar(type==='horse'?.85:type==='yak'?.9:1);}this.horse=this.animals.find(a=>a.type==='horse');this.dog=this.animals.find(a=>a.type==='dog');this.home=spawn;}
 relocate(spawn,all=true){this.home=spawn;for(const a of this.animals){if(!all&&a.type==='yak')continue;const r=a.type==='horse'?7:a.type==='dog'?4:38+hash(a.index,6)*35,angle=a.phase,p=this.geo.safePoint(spawn.x+Math.sin(angle)*r,spawn.z+Math.cos(angle)*r,45,(x,z)=>this.landscape.collides(x,z,.8)||this.landscape.obstacleTest?.(x,z));a.x=a.homeX=p.x;a.z=a.homeZ=p.z;a.group.position.set(p.x,p.y,p.z);}}
 update(dt,time,player,state){for(const a of this.animals){const distance=Math.hypot(a.x-player.x,a.z-player.z);a.group.visible=distance<450;if(a.type==='horse'&&state.riding){a.x=player.x;a.z=player.z;a.angle=state.yaw;const gallop=state.moving&&state.running,phase=time*(gallop?12:7),bob=state.moving?Math.sin(phase*2)*(gallop?.065:.025):0;a.group.position.set(a.x,player.y+bob,a.z);a.group.rotation.set(gallop?Math.sin(phase)*.035:0,a.angle,0);for(let k=0;k<a.legs.length;k++){const offset=gallop?[0,.48,2.5,3][k]:[0,Math.PI,Math.PI,0][k];a.legs[k].rotation.x=state.moving?Math.sin(phase+offset)*(gallop?.82:.4):0;}if(a.tail)a.tail.rotation.x=a.tailRestX+(gallop?-.3:0);continue;}a.group.rotation.x=0;if(a.type==='horse'&&a.tail)a.tail.rotation.x=a.tailRestX;let moving=false,speed=0;
   if((a.type==='dog'&&(state.dogAdopted||a.calling)&&distance>3.5)||(a.type==='horse'&&a.calling&&distance>5)){a.angle=Math.atan2(-(player.x-a.x),-(player.z-a.z));moving=true;speed=a.type==='dog'?5.2:6.5;if(distance>180){const p=this.geo.safePoint(player.x+7,player.z+7,30,(x,z)=>this.landscape.collides(x,z,.8)||this.landscape.obstacleTest?.(x,z));a.x=p.x;a.z=p.z;}}
   else if(a.type==='yak'||a.type==='dog'&&!state.dogAdopted){moving=Math.sin(time*.11+a.phase)>.3;speed=a.type==='yak'?.45:1.1;a.angle+=Math.sin(time*.15+a.phase)*dt*.18;if(Math.hypot(a.x-a.homeX,a.z-a.homeZ)>20)a.angle=Math.atan2(a.x-a.homeX,a.z-a.homeZ);}
   if(moving){const p=moveGround(this.walkGeo,{x:a.x,z:a.z},-Math.sin(a.angle)*speed*dt,-Math.cos(a.angle)*speed*dt,(x,z)=>this.landscape.collides(x,z,.25)||this.landscape.obstacleTest?.(x,z));if(Math.hypot(p.x-a.x,p.z-a.z)<.001)a.angle+=dt;a.x=p.x;a.z=p.z;}if(a.calling&&distance<5)a.calling=false;a.group.position.set(a.x,this.ground(a.x,a.z)+(moving?Math.sin(time*8)*.025:0),a.z);a.group.rotation.y=a.angle;for(let k=0;k<a.legs.length;k++)a.legs[k].rotation.x=moving?Math.sin(time*speed*3.4+(k%2)*Math.PI)*.32:0;if(a.tail)a.tail.rotation.z=Math.sin(time*(a.type==='dog'?7:1.5)+a.phase)*.11;
  }}
}
